"""Legacy state generated by an OLDER coordinator through its own public APIs, for upgrade and
replay regressions of the current coordinator.

``load_baseline(ref)`` reads ``automation/unattended`` at a git ref (``git show``) into an
isolated package under a temporary directory and imports it under a unique name, so the
baseline Coordinator/Store/Policy run unmodified next to the current ones. ``generate(ref,
out_dir)`` drives that baseline through the scenario matrix below with the in-memory GitHub
transport, a real local git worktree and a deterministic commit, and writes every resulting
run directory (``<out_dir>/<scenario>/runs/run-1/…``) plus ``manifest.json``. Nothing in a
generated story file is edited by hand: the only post-generation edits are the labelled
relocation of ``claim.worktree_path`` to a fresh deterministic worktree at load time
(``materialize``) and the explicitly labelled synthetic mutation of the ``*-done-proposal``
scenarios (a completed proposal whose phase transition was not persisted), which the baseline
cannot persist on its own because it writes the intent completion and the phase in one write.

The committed copy under ``fixtures/legacy-bb4c3ee/`` was generated from
``bb4c3ee480ed9094a67f1a18030e65be9a2a782c`` (the baseline the success-evidence repair of
2026-11-07 reviewed against, whose bug let an unsuccessful execution record a head or a
verdict). Regenerate with ``PYTHONPATH=. python3 -m automation.tests.legacy_baseline
--ref bb4c3ee --out automation/tests/fixtures/legacy-bb4c3ee``. The tests use the committed
copy and, when the ref is reachable in the local repository, also regenerate it into a
temporary directory and run the same assertions on that fresh generation."""

from __future__ import annotations

import argparse
import importlib
import importlib.util
import json
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

from automation.tests.fake_transport import CrashAfterEffect, small_backlog
from automation.tests.support import IMPLEMENTER, REVIEWER, ROOT, ok_worktree, passing_runner, failing_runner, write_policy
from automation.unattended.errors import Outage
from automation.unattended.github import PullRequestRecord

BASELINE_REF = "bb4c3ee480ed9094a67f1a18030e65be9a2a782c"
FIXTURE_DIR = Path(__file__).resolve().parent / "fixtures" / "legacy-bb4c3ee"
S = "OM-01.02"
PR = 7
UNSUCCESSFUL = ("interrupted", "failed", "cancelled")
STATUSES = UNSUCCESSFUL + ("completed",)
MODULES = ("__init__", "backlog", "eligibility", "errors", "github", "policy", "probes", "receipts", "state", "coordinator")
GIT_ENV = {"GIT_AUTHOR_NAME": "t", "GIT_AUTHOR_EMAIL": "t@example.invalid", "GIT_COMMITTER_NAME": "t", "GIT_COMMITTER_EMAIL": "t@example.invalid",
           "GIT_AUTHOR_DATE": "2026-11-06T12:00:00Z", "GIT_COMMITTER_DATE": "2026-11-06T12:00:00Z", "PATH": "/usr/bin:/bin:/usr/local/bin"}


def ref_reachable(ref: str = BASELINE_REF) -> bool:
    out = subprocess.run(["git", "-C", str(ROOT), "cat-file", "-e", f"{ref}^{{commit}}"], capture_output=True, check=False)
    return out.returncode == 0


def deterministic_repo(path: Path, branch: str = "t3/om-01-02") -> str:
    """A real git repository whose single commit has a fixed sha (fixed author/committer dates)."""
    path.mkdir(parents=True, exist_ok=True)
    env = {**GIT_ENV, "HOME": str(path)}
    subprocess.run(["git", "init", "-q", "-b", branch], cwd=path, check=True, env=env)
    (path / "README").write_text("x\n")
    subprocess.run(["git", "add", "README"], cwd=path, check=True, env=env)
    subprocess.run(["git", "-c", "commit.gpgsign=false", "commit", "-q", "-m", "init"], cwd=path, check=True, env=env)
    return subprocess.run(["git", "rev-parse", "HEAD"], cwd=path, check=True, capture_output=True, text=True, env=env).stdout.strip()


def load_baseline(ref: str, workdir: Path):
    """Import ``automation/unattended`` as of ``ref`` as an isolated package; returns the module
    namespace ``{name: module}``."""
    name = f"legacy_unattended_{ref[:12]}"
    pkg = workdir / name
    pkg.mkdir(parents=True, exist_ok=True)
    for mod in MODULES:
        text = subprocess.run(["git", "-C", str(ROOT), "show", f"{ref}:automation/unattended/{mod}.py"], capture_output=True, text=True, check=True).stdout
        (pkg / f"{mod}.py").write_text(text, encoding="utf-8")
    sys.path.insert(0, str(workdir))
    try:
        for mod in ("state", "coordinator", "policy", "backlog"):
            importlib.import_module(f"{name}.{mod}")
    finally:
        sys.path.remove(str(workdir))
    return {mod: sys.modules[f"{name}.{mod}"] for mod in ("state", "coordinator", "policy", "backlog")}


class BaselineHarness:
    """The baseline coordinator over a temporary store, the fake transport and a deterministic worktree."""

    def __init__(self, baseline: dict, tmp: Path):
        self.fake = small_backlog()
        self.policy_path = write_policy(tmp, allow='["OM-01.02"]')
        self.policy = baseline["policy"].load_policy(self.policy_path)
        self.state_dir = tmp / "runs"
        self.store = baseline["state"].Store(self.state_dir, "run-1")
        self.coordinator = baseline["coordinator"].Coordinator(self.fake, self.policy, self.store, live=True)
        self.snapshot = baseline["backlog"].take_snapshot(self.fake, "gabrianoo/owl-mast", "2026-11-06T12:00:00Z")
        self.worktree = tmp / "wt"
        self.sha = deterministic_repo(self.worktree)

    def terminal(self, status):
        state = self.store.load_story(S)
        return {"taskId": state.active_task["taskId"], "runId": state.active_task["runId"], "status": status}

    def claim(self):
        self.coordinator.reserve(S, self.snapshot, "c5d9d2e")
        return self.coordinator.bind_receipt(S, IMPLEMENTER, str(self.worktree), "t3/om-01-02", ok_worktree)

    def implementer_terminal_then_head(self, status):
        """Baseline bug: release the implementer with ``status`` (record-task-terminal), then a
        fresh baseline process records the head without evidence."""
        self.claim()
        self.coordinator.record_task_terminal(S, self.terminal(status))
        return self.coordinator.record_head(S, self.sha)

    def checks(self, runner=passing_runner):
        return self.coordinator.run_checks(S, self.sha, str(self.worktree), runner)

    def review(self, status, verdict="approved"):
        self.coordinator.authorize_review(S, self.sha)
        self.coordinator.bind_receipt(S, REVIEWER, worktree_check=ok_worktree)
        self.coordinator.record_task_terminal(S, self.terminal(status))
        return self.coordinator.record_review(S, self.sha, verdict, "report.md")

    def pending_proposal(self):
        """A proposal attempt whose POST failed once: the intent is persisted pending, nothing landed."""
        self.fake.pull_requests[PR] = PullRequestRecord(PR, "OPEN", self.sha, False, (), "SUCCESS")
        self.fake.fail_once["post_comment"] = Outage("503")
        try:
            self.coordinator.propose_evidence(S, self.sha, PR, ["OM-01.02-T1"], "summary")
        except Outage:
            pass
        return self.store.load_story(S)

    def landed_proposal(self):
        """A proposal whose comment landed but the process died before the checkpoint: the
        intent is pending and its marker exists on the issue."""
        self.fake.pull_requests[PR] = PullRequestRecord(PR, "OPEN", self.sha, False, (), "SUCCESS")
        self.fake.crash_after_post = True
        try:
            self.coordinator.propose_evidence(S, self.sha, PR, ["OM-01.02-T1"], "summary")
        except CrashAfterEffect:
            pass
        return self.store.load_story(S)

    def done_proposal(self):
        self.fake.pull_requests[PR] = PullRequestRecord(PR, "OPEN", self.sha, False, (), "SUCCESS")
        return self.coordinator.propose_evidence(S, self.sha, PR, ["OM-01.02-T1"], "summary")


def scenarios() -> dict[str, tuple[str, callable]]:
    """name -> (description, builder(BaselineHarness))."""
    out = {}
    for st in STATUSES:
        out[f"implementer-{st}-head-recorded"] = (f"implementer released as {st}, head recorded by the baseline (bug for unsuccessful)", lambda h, st=st: h.implementer_terminal_then_head(st))
        out[f"implementer-{st}-checks-passed"] = (f"…then the baseline ran passing checks", lambda h, st=st: (h.implementer_terminal_then_head(st), h.checks()))
        out[f"implementer-{st}-checks-failed"] = (f"…then the baseline ran failing checks", lambda h, st=st: (h.implementer_terminal_then_head(st), h.checks(failing_runner)))
        out[f"implementer-{st}-review-approved"] = (f"…checks passed, a completed reviewer approved", lambda h, st=st: (h.implementer_terminal_then_head(st), h.checks(), h.review("completed")))
        out[f"implementer-{st}-pending-proposal"] = (f"…approved, proposal POST failed once (pending intent, nothing landed)", lambda h, st=st: (h.implementer_terminal_then_head(st), h.checks(), h.review("completed"), h.pending_proposal()))
        out[f"implementer-{st}-landed-proposal"] = (f"…approved, proposal landed, crash before checkpoint (pending intent, marker on the issue)", lambda h, st=st: (h.implementer_terminal_then_head(st), h.checks(), h.review("completed"), h.landed_proposal()))
        out[f"implementer-{st}-done-proposal"] = (f"…approved and proposed (done); LABELLED SYNTHETIC MUTATION: phase reset to review-approved (transition not persisted)", lambda h, st=st: (h.implementer_terminal_then_head(st), h.checks(), h.review("completed"), h.done_proposal()))
        out[f"reviewer-{st}-review-approved"] = (f"completed implementer, reviewer released as {st}, approval recorded by the baseline (bug for unsuccessful)", lambda h, st=st: (h.implementer_terminal_then_head("completed"), h.checks(), h.review(st)))
        out[f"reviewer-{st}-pending-proposal"] = (f"…approval over a {st} reviewer, proposal POST failed once (pending intent)", lambda h, st=st: (h.implementer_terminal_then_head("completed"), h.checks(), h.review(st), h.pending_proposal()))
        out[f"reviewer-{st}-landed-proposal"] = (f"…approval over a {st} reviewer, proposal landed, crash before checkpoint", lambda h, st=st: (h.implementer_terminal_then_head("completed"), h.checks(), h.review(st), h.landed_proposal()))
        out[f"reviewer-{st}-done-proposal"] = (f"…approval over a {st} reviewer, proposed (done); LABELLED SYNTHETIC MUTATION: phase reset to review-approved", lambda h, st=st: (h.implementer_terminal_then_head("completed"), h.checks(), h.review(st), h.done_proposal()))
    return out


def generate(ref: str, out_dir: Path) -> dict:
    out_dir = Path(out_dir)
    if out_dir.exists():
        shutil.rmtree(out_dir)
    out_dir.mkdir(parents=True)
    manifest = {"ref": ref, "sha": None, "scenarios": {}}
    with tempfile.TemporaryDirectory() as work:
        baseline = load_baseline(ref, Path(work) / "pkg")
        for name, (description, build) in scenarios().items():
            with tempfile.TemporaryDirectory() as tmp:
                h = BaselineHarness(baseline, Path(tmp))
                manifest["sha"] = h.sha
                build(h)
                story_path = h.store.story_path(S)
                raw = json.loads(story_path.read_text())
                mutation = None
                if name.endswith("-done-proposal"):
                    assert raw["phase"] == "proposed" and raw["intents"][-1]["status"] == "done"
                    raw["phase"] = "review-approved"
                    mutation = "phase reset from proposed to review-approved after generation (completed proposal whose transition was not persisted)"
                    story_path.write_text(json.dumps(raw, indent=1, sort_keys=True))
                shutil.copytree(h.state_dir, out_dir / name / "runs", ignore=shutil.ignore_patterns(".lock"))
                comments = [{"issue": n, "comment_id": c.comment_id, "body": c.body} for n, cs in h.fake.comments.items() for c in cs]
                (out_dir / name / "github.json").write_text(json.dumps({"comments": comments, "pull_requests": {str(n): [p.number, p.state, p.head_sha, p.merged, list(p.reviews), p.checks] for n, p in h.fake.pull_requests.items()}}, indent=1))
                manifest["scenarios"][name] = {"description": description, "phase": raw["phase"], "head_sha": raw["head_sha"], "approved_sha": raw["approved_sha"],
                                               "task_history": [{k: r.get(k) for k in ("taskId", "runId", "role", "status", "successful", "authorization")} for r in raw["task_history"]],
                                               "intents": [{"op": i["op"], "status": i["status"], "comment_id": i["comment_id"]} for i in raw["intents"]],
                                               "worktree_path_at_generation": raw["claim"]["worktree_path"], "synthetic_mutation": mutation}
    (out_dir / "manifest.json").write_text(json.dumps(manifest, indent=1, sort_keys=True))
    return manifest


def materialize(fixture_dir: Path, name: str, tmp: Path):
    """Copy a generated scenario into ``tmp`` and relocate ``claim.worktree_path`` to a fresh
    deterministic worktree (same sha). Returns (fake, state_dir, worktree, sha, manifest entry)."""
    from automation.unattended.github import Comment
    manifest = json.loads((Path(fixture_dir) / "manifest.json").read_text())
    state_dir = tmp / "runs"
    shutil.copytree(Path(fixture_dir) / name / "runs", state_dir)
    worktree = tmp / "wt"
    sha = deterministic_repo(worktree)
    assert sha == manifest["sha"], (sha, manifest["sha"])
    story_path = state_dir / "run-1" / "stories" / f"{S}.json"
    raw = json.loads(story_path.read_text())
    raw["claim"]["worktree_path"] = str(worktree)  # labelled relocation only; no other field is edited
    story_path.write_text(json.dumps(raw, indent=1, sort_keys=True))
    gh = json.loads((Path(fixture_dir) / name / "github.json").read_text())
    fake = small_backlog()
    for c in gh["comments"]:
        fake.comments.setdefault(c["issue"], []).append(Comment(c["comment_id"], c["body"], "machine", "2026-11-06T13:00:00Z"))
    for n, p in gh["pull_requests"].items():
        fake.pull_requests[int(n)] = PullRequestRecord(p[0], p[1], p[2], p[3], tuple(p[4]), p[5])
    return fake, state_dir, worktree, sha, manifest["scenarios"][name]


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    ap.add_argument("--ref", default=BASELINE_REF)
    ap.add_argument("--out", default=str(FIXTURE_DIR))
    args = ap.parse_args()
    manifest = generate(args.ref, Path(args.out))
    print(json.dumps({"ref": manifest["ref"], "sha": manifest["sha"], "scenarios": len(manifest["scenarios"])}))


if __name__ == "__main__":
    main()
